frappe.ui.form.on('Company', {
    async refresh(frm) {
        if (!frm.doc.name || frm.is_new()) return;
        const stats_field = frm.fields_dict.custom_fbr_stats_html;
        if (!stats_field || !stats_field.$wrapper) return;
        const placeholder = '<div class="fbr-stats-placeholder text-muted">Loading FBR statistics...</div>';
        stats_field.$wrapper.html(placeholder);
        try {
            const r = await frappe.call({
                method: 'fbr_e_invoicing.utils.get_company_fbr_stats',
                args: { company: frm.doc.name }
            });
            const stats = (r && r.message) || {};
            const total = stats.total || 0;
            const sales = stats.sales_invoice || 0;
            const pos = stats.pos_invoice || 0;
            const html = ''
                + '<div class="fbr-stats-grid">'
                +   '<div class="fbr-stat"><div class="fbr-stat-value">' + total + '</div><div class="fbr-stat-label">Total Posted</div></div>'
                +   '<div class="fbr-stat"><div class="fbr-stat-value">' + sales + '</div><div class="fbr-stat-label">Sales Invoices</div></div>'
                +   '<div class="fbr-stat"><div class="fbr-stat-value">' + pos + '</div><div class="fbr-stat-label">POS Invoices</div></div>'
                + '</div>'
                + '<style>'
                +   '.fbr-stats-grid { display:flex; gap:24px; padding:8px 0; flex-wrap:wrap; }'
                +   '.fbr-stat { text-align:center; min-width:120px; padding:12px 16px; background:#f8fafc; border:1px solid #e5e7eb; border-radius:8px; }'
                +   '.fbr-stat-value { font-size:24px; font-weight:700; color:#1f2937; line-height:1.2; }'
                +   '.fbr-stat-label { font-size:12px; color:#6b7280; margin-top:4px; }'
                + '</style>';
            stats_field.$wrapper.html(html);
        } catch (e) {
            stats_field.$wrapper.html('<div class="text-muted">FBR statistics unavailable.</div>');
            console.error('Failed to load FBR stats', e);
        }
    }
});
